// Builds the CommonJS copy in lib/ that the published CLI loads (bin/timer.cjs). Do not edit lib/ by hand.
import { readFileSync, writeFileSync } from "node:fs";

const source = readFileSync(new URL("../src/duration.js", import.meta.url), "utf8");
const names = [...source.matchAll(/^export function (\w+)/gm)].map((m) => m[1]);
const body = source.replace(/^export function/gm, "function");
const header = "// GENERATED by scripts/build.mjs from src/duration.js. Do not edit.\n\"use strict\";\n";
writeFileSync(new URL("../lib/duration.cjs", import.meta.url), `${header}${body}\nmodule.exports = { ${names.join(", ")} };\n`);
console.log(`built lib/duration.cjs (${names.join(", ")})`);
